public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    int n = Integer.parseInt(sc.next());
    int m = Integer.parseInt(sc.next());
    int k = Integer.parseInt(sc.next());
    List<Test> tests = new ArrayList<>();
    for (int i = 0; i < m; i++) {
        int C = Integer.parseInt(sc.next());
        int keys = 0;
        for (int j = 0; j < C; j++) {
            int A = Integer.parseInt(sc.next());
            keys |= 1 << (A - 1);
        }
        char r = sc.next().charAt(0);
        tests.add(new Test(keys, r));
    }
    int validCombinations = 0;
    for (int combination = 0; combination < (1 << n); combination++) {
        boolean isValid = true;
        for (Test test : tests) {
            int realKeys = Integer.bitCount(combination & test.keys);
            if ((test.result == 'o' && realKeys < k) || (test.result == 'x' && realKeys >= k)) {
                isValid = false;
                break;
            }
        }
        if (isValid) {
            validCombinations++;
        }
    }
    System.out.println(validCombinations);
}

static class Test {
    int keys;
    char result;

    Test(int keys, char result) {
        this.keys = keys;
        this.result = result;
    }
}
